[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>CreativeHub — Online Classes for Creatives</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700;800&family=Work+Sans:wght@300;400;500;600&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --clr-primary: #000000;
      --clr-accent-green: #55DA9B;
      --clr-accent-purple: #5620C1;
      --clr-white: #FFFFFF;
      --clr-bg: #FAFAFA;
      --clr-bg-alt: #F3F4F6;
      --clr-text: #1F2937;
      --clr-text-light: #6B7280;
      --clr-border: #E5E7EB;
      --radius-sm: 8px;
      --radius-md: 12px;
      --radius-lg: 16px;
      --radius-xl: 24px;
      --radius-full: 9999px;
      --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
      --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.1), 0 2px 4px -2px rgba(0,0,0,0.1);
      --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.1), 0 4px 6px -4px rgba(0,0,0,0.1);
      --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.1), 0 8px 10px -6px rgba(0,0,0,0.1);
      --transition: 150ms ease;
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: 'Work Sans', sans-serif;
      color: var(--clr-text);
      background: var(--clr-white);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
    }

    h1, h2, h3, h4, h5, h6 {
      font-family: 'Outfit', sans-serif;
      font-weight: 700;
      line-height: 1.2;
    }

    a { color: inherit; text-decoration: none; }
    button { font-family: inherit; cursor: pointer; border: none; background: none; }
    img { max-width: 100%; display: block; }

    .container {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 24px;
    }

    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
      padding: 12px 24px;
      border-radius: var(--radius-full);
      font-weight: 600;
      font-size: 15px;
      transition: all var(--transition);
    }

    .btn:focus-visible {
      outline: 3px solid var(--clr-accent-green);
      outline-offset: 2px;
    }

    .btn-primary {
      background: var(--clr-accent-green);
      color: var(--clr-primary);
    }

    .btn-primary:hover { background: #3fc887; transform: translateY(-1px); }
    .btn-primary:active { transform: translateY(0); }

    .btn-secondary {
      background: var(--clr-primary);
      color: var(--clr-white);
    }

    .btn-secondary:hover { background: #1a1a1a; transform: translateY(-1px); }
    .btn-secondary:active { transform: translateY(0); }

    .btn-outline {
      background: transparent;
      border: 2px solid var(--clr-border);
      color: var(--clr-text);
    }

    .btn-outline:hover { border-color: var(--clr-text); }

    /* ===== HEADER ===== */
    header {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      z-index: 100;
      background: rgba(255,255,255,0.9);
      backdrop-filter: blur(12px);
      border-bottom: 1px solid var(--clr-border);
    }

    header .container {
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 64px;
    }

    .logo {
      font-family: 'Outfit', sans-serif;
      font-weight: 800;
      font-size: 22px;
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .logo-dot {
      width: 10px;
      height: 10px;
      background: var(--clr-accent-green);
      border-radius: 50%;
    }

    nav { display: flex; align-items: center; gap: 32px; }

    nav a {
      font-size: 14px;
      font-weight: 500;
      color: var(--clr-text-light);
      transition: color var(--transition);
    }

    nav a:hover { color: var(--clr-text); }

    .nav-actions { display: flex; align-items: center; gap: 12px; }

    .nav-actions .btn { padding: 8px 16px; font-size: 14px; }

    /* ===== HERO ===== */
    .hero {
      padding: 140px 0 80px;
      background: var(--clr-primary);
      color: var(--clr-white);
      position: relative;
      overflow: hidden;
    }

    .hero::before {
      content: '';
      position: absolute;
      top: -50%;
      right: -20%;
      width: 600px;
      height: 600px;
      background: radial-gradient(circle, rgba(86,32,193,0.3) 0%, transparent 70%);
      pointer-events: none;
    }

    .hero::after {
      content: '';
      position: absolute;
      bottom: -30%;
      left: -10%;
      width: 400px;
      height: 400px;
      background: radial-gradient(circle, rgba(85,218,155,0.2) 0%, transparent 70%);
      pointer-events: none;
    }

    .hero-content {
      position: relative;
      z-index: 1;
      text-align: center;
      max-width: 800px;
      margin: 0 auto;
    }

    .hero h1 {
      font-size: clamp(36px, 6vw, 64px);
      font-weight: 800;
      margin-bottom: 16px;
      letter-spacing: -0.02em;
    }

    .hero h1 span { color: var(--clr-accent-green); }

    .hero-subtitle {
      font-size: 20px;
      color: rgba(255,255,255,0.8);
      margin-bottom: 32px;
    }

    .hero-ctas {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 12px;
      margin-bottom: 40px;
      flex-wrap: wrap;
    }

    .hero-ctas .btn { padding: 14px 28px; font-size: 16px; }

    .hero-ctas .btn-google {
      background: var(--clr-white);
      color: var(--clr-primary);
    }

    .hero-ctas .btn-google:hover { background: #f5f5f5; }

    .hero-ctas .btn-email {
      background: var(--clr-accent-green);
      color: var(--clr-primary);
    }

    .hero-legal {
      font-size: 11px;
      color: rgba(255,255,255,0.5);
      max-width: 500px;
      margin: 0 auto;
      line-height: 1.5;
    }

    .category-pills {
      display: flex;
      flex-wrap: wrap;
      justify-content: center;
      gap: 8px;
      margin-top: 48px;
    }

    .category-pill {
      padding: 8px 16px;
      border-radius: var(--radius-full);
      background: rgba(255,255,255,0.1);
      color: rgba(255,255,255,0.9);
      font-size: 13px;
      font-weight: 500;
      transition: all var(--transition);
      cursor: pointer;
      border: 1px solid transparent;
    }

    .category-pill:hover, .category-pill:focus {
      background: rgba(255,255,255,0.2);
      border-color: rgba(255,255,255,0.3);
    }

    /* ===== FEATURES ===== */
    .features {
      padding: 80px 0;
      background: var(--clr-white);
    }

    .features-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
      gap: 32px;
    }

    .feature-card {
      text-align: center;
      padding: 32px 24px;
    }

    .feature-icon {
      width: 56px;
      height: 56px;
      margin: 0 auto 20px;
      background: linear-gradient(135deg, var(--clr-accent-green), #3dbd7d);
      border-radius: var(--radius-lg);
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .feature-icon svg {
      width: 28px;
      height: 28px;
      color: var(--clr-primary);
    }

    .feature-card h3 {
      font-size: 18px;
      margin-bottom: 8px;
    }

    .feature-card p {
      font-size: 14px;
      color: var(--clr-text-light);
    }

    .features-header {
      text-align: center;
      margin-bottom: 48px;
    }

    .features-header h2 {
      font-size: clamp(28px, 4vw, 40px);
      margin-bottom: 12px;
    }

    .features-header p {
      font-size: 18px;
      color: var(--clr-text-light);
      max-width: 600px;
      margin: 0 auto;
    }

    /* ===== STATS ===== */
    .stats {
      background: var(--clr-accent-purple);
      padding: 64px 0;
      color: var(--clr-white);
    }

    .stats-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 32px;
      text-align: center;
    }

    .stat-item h3 {
      font-size: clamp(36px, 5vw, 56px);
      font-weight: 800;
      margin-bottom: 4px;
    }

    .stat-item p {
      font-size: 14px;
      opacity: 0.8;
      text-transform: uppercase;
      letter-spacing: 0.05em;
    }

    /* ===== COURSES ===== */
    .courses {
      padding: 80px 0;
      background: var(--clr-bg);
    }

    .section-header {
      text-align: center;
      margin-bottom: 40px;
    }

    .section-header h2 {
      font-size: clamp(28px, 4vw, 40px);
      margin-bottom: 12px;
    }

    .section-header p {
      font-size: 16px;
      color: var(--clr-text-light);
    }

    .course-tabs {
      display: flex;
      gap: 8px;
      flex-wrap: wrap;
      justify-content: center;
      margin-bottom: 32px;
    }

    .course-tab {
      padding: 10px 20px;
      border-radius: var(--radius-full);
      font-size: 14px;
      font-weight: 500;
      background: var(--clr-white);
      border: 1px solid var(--clr-border);
      color: var(--clr-text-light);
      transition: all var(--transition);
      cursor: pointer;
    }

    .course-tab:hover { border-color: var(--clr-text); color: var(--clr-text); }

    .course-tab.active {
      background: var(--clr-primary);
      color: var(--clr-white);
      border-color: var(--clr-primary);
    }

    .course-tab:focus-visible {
      outline: 3px solid var(--clr-accent-green);
      outline-offset: 2px;
    }

    .courses-grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
      gap: 24px;
    }

    .course-card {
      background: var(--clr-white);
      border-radius: var(--radius-lg);
      overflow: hidden;
      box-shadow: var(--shadow-sm);
      transition: all var(--transition);
    }

    .course-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-lg);
    }

    .course-card:focus-within {
      outline: 3px solid var(--clr-accent-green);
      outline-offset: 2px;
    }

    .course-thumb {
      width: 100%;
      aspect-ratio: 16/10;
      object-fit: cover;
      background: var(--clr-bg-alt);
    }

    .course-info { padding: 16px; }

    .course-info h4 {
      font-size: 15px;
      font-weight: 600;
      margin-bottom: 8px;
      line-height: 1.4;
    }

    .course-meta {
      display: flex;
      align-items: center;
      justify-content: space-between;
      font-size: 13px;
      color: var(--clr-text-light);
    }

    .course-meta .students { display: flex; align-items: center; gap: 4px; }

    .course-instructor {
      font-size: 13px;
      color: var(--clr-text-light);
      margin-bottom: 8px;
    }

    .course-duration {
      display: inline-flex;
      align-items: center;
      gap: 4px;
      font-size: 12px;
      color: var(--clr-text-light);
      background: var(--clr-bg);
      padding: 4px 10px;
      border-radius: var(--radius-full);
    }

    /* ===== CREATIVE FEED ===== */
    .creative-feed {
      padding: 80px 0;
      background: var(--clr-white);
    }

    .feed-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
      gap: 24px;
    }

    .feed-card {
      background: var(--clr-bg);
      border-radius: var(--radius-xl);
      padding: 32px;
      text-align: center;
      transition: all var(--transition);
    }

    .feed-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-md);
    }

    .feed-icon {
      width: 64px;
      height: 64px;
      margin: 0 auto 20px;
      background: linear-gradient(135deg, var(--clr-accent-green), var(--clr-accent-purple));
      border-radius: var(--radius-lg);
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .feed-icon svg {
      width: 32px;
      height: 32px;
      color: var(--clr-white);
    }

    .feed-card h3 {
      font-size: 20px;
      margin-bottom: 8px;
    }

    .feed-card p {
      font-size: 14px;
      color: var(--clr-text-light);
      line-height: 1.6;
    }

    /* ===== TEACHERS ===== */
    .teachers {
      padding: 80px 0;
      background: var(--clr-bg);
    }

    .teachers-carousel {
      display: flex;
      gap: 24px;
      overflow-x: auto;
      scroll-snap-type: x mandatory;
      -webkit-overflow-scrolling: touch;
      padding: 8px 0 24px;
      scrollbar-width: none;
    }

    .teachers-carousel::-webkit-scrollbar { display: none; }

    .teacher-card {
      flex: 0 0 280px;
      scroll-snap-align: start;
      background: var(--clr-white);
      border-radius: var(--radius-xl);
      padding: 32px 24px;
      text-align: center;
      box-shadow: var(--shadow-sm);
      transition: all var(--transition);
    }

    .teacher-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-md);
    }

    .teacher-avatar {
      width: 96px;
      height: 96px;
      border-radius: 50%;
      margin: 0 auto 16px;
      object-fit: cover;
      background: var(--clr-bg-alt);
      display: flex;
      align-items: center;
      justify-content: center;
      font-family: 'Outfit', sans-serif;
      font-size: 32px;
      font-weight: 700;
      color: var(--clr-white);
    }

    .teacher-card h3 { font-size: 18px; margin-bottom: 4px; }

    .teacher-specialty {
      font-size: 14px;
      color: var(--clr-accent-purple);
      font-weight: 500;
    }

    /* ===== TESTIMONIALS ===== */
    .testimonials {
      padding: 80px 0;
      background: var(--clr-primary);
      color: var(--clr-white);
    }

    .testimonials .section-header h2 { color: var(--clr-white); }

    .testimonials-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
      gap: 24px;
    }

    .testimonial-card {
      background: rgba(255,255,255,0.08);
      border-radius: var(--radius-xl);
      padding: 32px;
      position: relative;
    }

    .testimonial-card::before {
      content: '"';
      font-family: 'Outfit', sans-serif;
      font-size: 64px;
      color: var(--clr-accent-green);
      position: absolute;
      top: 16px;
      left: 24px;
      line-height: 1;
      opacity: 0.5;
    }

    .testimonial-quote {
      font-size: 16px;
      line-height: 1.7;
      margin-bottom: 20px;
      position: relative;
      z-index: 1;
    }

    .testimonial-author {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .testimonial-avatar {
      width: 40px;
      height: 40px;
      border-radius: 50%;
      background: var(--clr-accent-purple);
      display: flex;
      align-items: center;
      justify-content: center;
      font-family: 'Outfit', sans-serif;
      font-weight: 600;
      font-size: 14px;
    }

    .testimonial-name { font-weight: 600; font-size: 14px; }

    /* ===== TEAMS ===== */
    .teams {
      padding: 80px 0;
      background: linear-gradient(135deg, var(--clr-accent-green), #3dbd7d);
      text-align: center;
    }

    .teams h2 {
      font-size: clamp(28px, 4vw, 44px);
      margin-bottom: 16px;
    }

    .teams p {
      font-size: 18px;
      max-width: 600px;
      margin: 0 auto 32px;
      color: var(--clr-primary);
    }

    .teams .btn {
      background: var(--clr-primary);
      color: var(--clr-white);
      padding: 14px 32px;
      font-size: 16px;
    }

    .teams .btn:hover { background: #1a1a1a; }

    /* ===== FAQ ===== */
    .faq {
      padding: 80px 0;
      background: var(--clr-bg);
    }

    .faq-list {
      max-width: 800px;
      margin: 0 auto;
    }

    .faq-item {
      border-bottom: 1px solid var(--clr-border);
    }

    .faq-question {
      width: 100%;
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 24px 0;
      font-size: 16px;
      font-weight: 600;
      text-align: left;
      cursor: pointer;
      background: none;
      border: none;
      font-family: inherit;
      color: var(--clr-text);
      transition: color var(--transition);
    }

    .faq-question:hover { color: var(--clr-accent-purple); }

    .faq-question:focus-visible {
      outline: 3px solid var(--clr-accent-green);
      outline-offset: 2px;
    }

    .faq-icon {
      width: 24px;
      height: 24px;
      flex-shrink: 0;
      transition: transform 0.2s ease;
    }

    .faq-item.open .faq-icon { transform: rotate(180deg); }

    .faq-answer {
      max-height: 0;
      overflow: hidden;
      transition: max-height 0.3s ease, padding 0.3s ease;
    }

    .faq-item.open .faq-answer {
      max-height: 300px;
      padding-bottom: 24px;
    }

    .faq-answer p {
      font-size: 15px;
      color: var(--clr-text-light);
      line-height: 1.7;
    }

    /* ===== FOOTER ===== */
    footer {
      background: var(--clr-primary);
      color: var(--clr-white);
      padding: 64px 0 32px;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
      gap: 40px;
      margin-bottom: 48px;
    }

    .footer-col h4 {
      font-size: 14px;
      font-weight: 600;
      margin-bottom: 16px;
      text-transform: uppercase;
      letter-spacing: 0.05em;
      color: rgba(255,255,255,0.6);
    }

    .footer-col ul { list-style: none; }

    .footer-col li { margin-bottom: 10px; }

    .footer-col a {
      font-size: 14px;
      color: rgba(255,255,255,0.8);
      transition: color var(--transition);
    }

    .footer-col a:hover { color: var(--clr-accent-green); }

    .footer-bottom {
      border-top: 1px solid rgba(255,255,255,0.1);
      padding-top: 32px;
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      justify-content: space-between;
      gap: 16px;
    }

    .footer-bottom p {
      font-size: 13px;
      color: rgba(255,255,255,0.5);
    }

    .footer-links {
      display: flex;
      gap: 24px;
    }

    .footer-links a {
      font-size: 13px;
      color: rgba(255,255,255,0.6);
    }

    .footer-links a:hover { color: var(--clr-white); }

    /* ===== RESPONSIVE ===== */
    @media (max-width: 768px) {
      nav { display: none; }

      .hero-ctas { flex-direction: column; }

      .hero-ctas .btn { width: 100%; }

      .stats-grid { grid-template-columns: repeat(2, 1fr); }

      .courses-grid { grid-template-columns: 1fr; }

      .teachers-carousel { gap: 16px; }

      .teacher-card { flex: 0 0 240px; }

      .footer-bottom { flex-direction: column; text-align: center; }
    }

    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
      }
    }
  </style>
</head>
<body>
  <!-- HEADER -->
  <header>
    <div class="container">
      <a href="#" class="logo">
        Creative<span style="color:var(--clr-accent-green)">Hub</span>
        <span class="logo-dot"></span>
      </a>
      <nav>
        <a href="#">Browse</a>
        <a href="#">Teach</a>
        <a href="#">Pricing</a>
        <a href="#">Teams</a>
      </nav>
      <div class="nav-actions">
        <a href="#" class="btn">Sign In</a>
        <a href="#" class="btn btn-primary">Start Free Trial</a>
      </div>
    </div>
  </header>

  <!-- HERO -->
  <section class="hero">
    <div class="container">
      <div class="hero-content">
        <h1><span>Creative Classes</span><br>Taught by the Best Creative Pros</h1>
        <p class="hero-subtitle">Get 7 free days of CreativeHub</p>
